var o=`0280-burek`;var t=`world-0280`;var i=`BA`;var r=`southern-europe`;var a=4;var l=85;var u={en:`Burek`,ua:`Бурек`};var s={en:`A traditional Bosnia and Herzegovina dish made with all-purpose flour, ground beef, yellow onion. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Боснія і Герцеговина. Основні інгредієнти: пшеничне борошно універсальне, яловичий фарш, жовта цибуля. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 23 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 23 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:23,i:[[`all-purpose-flour`,450,`g`],[`water`,260,`ml`],[`table-salt`,5,`g`],[`sunflower-oil`,20,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:8,i:[[`ground-beef`,520,`g`],[`yellow-onion`,220,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Stretch the rested dough until paper thin, dot with the beef-onion mixture, roll into long spirals and coil into a round baking pan.`,ua:`Розтягніть відпочиле тісто до напівпрозорості, розподіліть начинку з фаршу й цибулі, скрутіть довгі рулети та викладіть спіраллю у круглу форму.`,t:[`rolling-stuffed-food`],m:17,i:[]},{en:`Bake in a preheated 180°C oven for about 37 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 37 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:37,i:[[`sunflower-oil`,60,`ml`]]}];var g={slug:o,id:t,country:`BA`,region:r,servings:4,minutes:85,title:u,text:s,steps:d};export{i as country,g as default,t as id,l as minutes,r as region,a as servings,o as slug,d as steps,s as text,u as title};